Az alábbiakban egy teljes Flask backendet (main.py) és a frontendhez használható index.html-t találsz, ami a feltöltött HTML dizájnnal működik és az AWS Bedrock Claude Sonnet 4.5 modellt használja. A .env fájl a korábban leírtak szerint szükséges a futtatáshoz.[1][2]

***

### main.py

```python
import os
from flask import Flask, request, jsonify, send_from_directory
from anthropic import AnthropicBedrock
from flask_cors import CORS

app = Flask(__name__, static_folder=".")
CORS(app)

client = AnthropicBedrock(
    aws_access_key=os.getenv("AWS_ACCESS_KEY_ID"),
    aws_secret_key=os.getenv("AWS_SECRET_ACCESS_KEY"),
    aws_region=os.getenv("AWS_REGION"),
)

MODEL_ID = "global.anthropic.claude-sonnet-4-5-20250929-v1:0"

@app.route("/api/generate", methods=["POST"])
def generate():
    data = request.json
    messages = data.get("messages") or []
    # A frontend {'role', 'content', 'attachment'} formát használ, attachmentet most nem kezeljük
    conv = [{"role": m.get("role", "user"), "content": m.get("content", "")} for m in messages]

    response = client.messages.create(
        model=MODEL_ID,
        max_tokens=800,
        messages=conv,
    )
    result = {"content": response.content}
    return jsonify(result)

@app.route("/", methods=["GET"])
def root():
    return app.send_static_file("index.html")

@app.route("/<path:path>")
def static_proxy(path):
    # Minden mást a statikus könyvtárból szolgál ki, így a CSS/JS is működhet
    return send_from_directory('.', path)

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=True)
```

